package org.eclipse.jdt.internal.ui.infoviews;

import org.eclipse.jdt.core.IJavaElement;
import org.eclipse.jdt.internal.ui.JavaElementLabels;
import org.eclipse.jdt.internal.ui.javaeditor.JavaElementLinks;

public class JavadocView {
    // Original internal constants that JavadocHover would eventually encapsulate
    private static final long LABEL_FLAGS = JavaElementLabels.ALL_FULLY_QUALIFIED;
    private static final long LOCAL_VARIABLE_FLAGS = LABEL_FLAGS;
    private static final long TYPE_PARAMETER_FLAGS = LABEL_FLAGS;
    private static final long PACKAGE_FLAGS = LABEL_FLAGS;

    public String getInfoText(IJavaElement member) {
        // This is the line we want to match
        return JavaElementLinks.getElementLabel(member, getHeaderFlags(member));
    }

    // The method being refactored out of this class
    private long getHeaderFlags(IJavaElement element) {
        switch (element.getElementType()) {
            case IJavaElement.LOCAL_VARIABLE:
                return LOCAL_VARIABLE_FLAGS;
            case IJavaElement.TYPE_PARAMETER:
                return TYPE_PARAMETER_FLAGS;
            case IJavaElement.PACKAGE_FRAGMENT:
                return PACKAGE_FLAGS;
            default:
                return LABEL_FLAGS;
        }
    }
}

